('bond-yard-toy', 'BOND_YARD_TOY', 'Brinquedo de Pátio', 'Faz o próximo acontecimento do Pátio tentar envolver 3 ou mais mascotes e favorece a formação de um círculo social.', 'COMMON', 0, false, true, 906, '{"mode":"BONDS","effect":"groupEvent","source":"YARD"}', NOW()),
('bond-illustrated-invitation', 'BOND_ILLUSTRATED_INVITATION', 'Convite Ilustrado', 'Permite escolher um mascote presente como alvo preferencial do próximo encontro. Não garante amizade nem rivalidade.', 'UNCOMMON', 0, false, true, 907, '{"mode":"BONDS","effect":"targetNextEncounter","source":"YARD"}', NOW()),
